// CrypTAK Mesh Monitor — evaluates node health from meshRegistry
// Uses the live MQTT registry maintained by the WebMap tab

var registry = flow.get('meshRegistry') || {};
var monState = flow.get('meshMonState') || {};
var now = Math.floor(Date.now() / 1000);

// Monitored nodes config
var MONITORED = {
    '!a51e2838': { name: 'CrypTAK Base',  type: 'own', staleWarn: 300,  staleCrit: 1800  },
    '!dce7b97d': { name: 'CrypTAK-TRK01', type: 'own', staleWarn: 600,  staleCrit: 3600  },
    '!c6eadff0': { name: 'CrypTAK-SOL01', type: 'own', staleWarn: 1800, staleCrit: 7200  },
    '!3db00f2c': { name: 'CrypTAK-SOL02', type: 'own', staleWarn: 1800, staleCrit: 7200  },
    '!9aa4baf0': { name: 'CrypTAK-VHC01', type: 'own', staleWarn: 1800, staleCrit: 7200  },
    '!01f94ec0': { name: 'Tracker Alpha', type: 'own', staleWarn: 600,  staleCrit: 3600  },
    '!67af5da5': { name: 'BUMA',          type: 'community', staleWarn: 3600, staleCrit: 14400 },
    '!756f8df0': { name: 'Mesh 8df0',     type: 'community', staleWarn: 3600, staleCrit: 14400 }
};

var results = [];
var alerts = [];

for (var nid in MONITORED) {
    var cfg = MONITORED[nid];
    var live = registry[nid] || {};
    var prev = monState[nid] || { status: 'unknown', consecutiveMisses: 0 };

    var lastHeard = live.lastHeard || 0;
    var ago = lastHeard > 0 ? (now - lastHeard) : -1;

    // Determine status
    var status, icon;
    if (ago < 0) {
        status = 'unknown';
        icon = '⚪';
    } else if (ago <= cfg.staleWarn) {
        status = 'ok';
        icon = '🟢';
    } else if (ago <= cfg.staleCrit) {
        status = 'warn';
        icon = '🟡';
    } else {
        status = 'stale';
        icon = '🔴';
    }

    // Format age string
    var ageStr;
    if (ago < 0) ageStr = 'never';
    else if (ago < 60) ageStr = ago + 's ago';
    else if (ago < 3600) ageStr = Math.floor(ago/60) + 'm ago';
    else if (ago < 86400) ageStr = Math.floor(ago/3600) + 'h ago';
    else ageStr = Math.floor(ago/86400) + 'd ago';

    // Track consecutive misses (stale/unknown)
    var misses = prev.consecutiveMisses || 0;
    if (status === 'stale' || status === 'unknown') {
        misses++;
    } else {
        misses = 0;
    }

    // Generate alert on state transition to stale
    if (status === 'stale' && prev.status !== 'stale') {
        alerts.push({
            node: cfg.name,
            nodeId: nid,
            type: cfg.type,
            message: '⚠️ **' + cfg.name + '** went stale (last heard ' + ageStr + ')',
            severity: 'warn'
        });
    }

    // Alert on recovery
    if (status === 'ok' && (prev.status === 'stale' || prev.status === 'unknown')) {
        if (prev.status !== 'unknown' || prev.consecutiveMisses > 2) {
            alerts.push({
                node: cfg.name,
                nodeId: nid,
                type: cfg.type,
                message: '✅ **' + cfg.name + '** back online (heard ' + ageStr + ')',
                severity: 'info'
            });
        }
    }

    // Save state
    monState[nid] = {
        name: cfg.name,
        type: cfg.type,
        status: status,
        lastHeard: lastHeard,
        agoSecs: ago,
        ageStr: ageStr,
        snr: live.snrToBridge || null,
        hops: live.hopsToBridge || null,
        battery: live.battery || null,
        consecutiveMisses: misses,
        checkedAt: now
    };

    results.push({
        icon: icon,
        name: cfg.name,
        nid: nid,
        type: cfg.type,
        status: status,
        ageStr: ageStr,
        snr: live.snrToBridge,
        hops: live.hopsToBridge,
        misses: misses
    });
}

flow.set('meshMonState', monState);

// Build summary message
var lines = ['**Mesh Monitor** — ' + new Date().toISOString().replace('T', ' ').substring(0, 19) + ' UTC'];
lines.push('```');
results.forEach(function(r) {
    var snrStr = r.snr !== null && r.snr !== undefined ? r.snr.toFixed(1) + 'dB' : '  N/A';
    var hopStr = r.hops !== null && r.hops !== undefined ? r.hops + 'h' : ' ?';
    lines.push(r.icon + ' ' + r.name.padEnd(22) + ' ' + r.ageStr.padStart(10) + '  SNR:' + snrStr.padStart(8) + '  ' + hopStr);
});
lines.push('```');
var summary = lines.join('\n');

// Output 1: summary (for debug/dashboard)
// Output 2: alerts (for Discord webhook)
var msg1 = { payload: summary, results: results, state: monState };
var msg2 = alerts.length > 0 ? { payload: alerts } : null;

return [msg1, msg2];

// Write summary to log file
var fs = global.get('fs');
if (!fs) {
    // fs not available in global context, skip file logging
    return null;
}
var logLine = new Date().toISOString() + ' | ' + JSON.stringify(msg.results.map(function(r) { return r.icon + ' ' + r.name + ': ' + r.status + ' (' + r.ageStr + ')'; })) + '\n';

try {
    fs.appendFileSync('/data/mesh-monitor.log', logLine);
} catch(e) {
    node.warn('Could not write log: ' + e.message);
}
return null;

// Format alerts for Discord webhook
var alerts = msg.payload;
if (!alerts || alerts.length === 0) return null;

var messages = alerts.map(function(a) { return a.message; });
var content = messages.join('\n');

msg.payload = {
    content: content
};
return msg;

// Count packets per node for traffic stats
// Wire this to the same MQTT subscriber as WebMap
var payload = msg.payload;
if (!payload || !payload.from) return null;

var nodeId = '!' + payload.from.toString(16).padStart(8, '0');
var stats = flow.get('meshPacketStats') || {};

if (!stats[nodeId]) {
    stats[nodeId] = { total: 0, types: {} };
}

stats[nodeId].total++;
var msgType = payload.type || 'unknown';
stats[nodeId].types[msgType] = (stats[nodeId].types[msgType] || 0) + 1;
stats[nodeId].lastPacket = Date.now();

flow.set('meshPacketStats', stats);
return null;

var monState = flow.get('meshMonState') || {};
var pktStats = flow.get('meshPacketStats') || {};
var registry = flow.get('meshRegistry') || {};

var lines = ['**📡 Mesh Monitor — Full Status Report**'];
lines.push('Registry: ' + Object.keys(registry).length + ' nodes | Monitored: ' + Object.keys(monState).length);
lines.push('');
lines.push('```');

var sorted = Object.keys(monState).sort(function(a,b) {
    return monState[a].name.localeCompare(monState[b].name);
});

sorted.forEach(function(nid) {
    var n = monState[nid];
    var icon = {ok:'🟢', warn:'🟡', stale:'🔴', unknown:'⚪'}[n.status] || '❓';
    var snrStr = n.snr !== null && n.snr !== undefined ? n.snr.toFixed(1) + 'dB' : 'N/A';
    var hopStr = n.hops !== null && n.hops !== undefined ? n.hops + 'h' : '?';
    var bat = n.battery || 'N/A';
    var stats = pktStats[nid] || { total: 0 };

    lines.push(icon + ' ' + n.name.padEnd(22) + ' [' + n.type.padEnd(9) + ']');
    lines.push('    heard:' + n.ageStr.padStart(10) + '  SNR:' + snrStr.padStart(8) + '  hops:' + hopStr + '  bat:' + bat);
    lines.push('    pkts:' + stats.total + '  misses:' + n.consecutiveMisses);
});
lines.push('```');

msg.payload = lines.join('\n');
return msg;
